import re


_SCRIPT_START = re.compile(r"<script(?=[\t\n\f\r />])", re.IGNORECASE | re.ASCII)
_SCRIPT_END = re.compile(r"</script(?=[\t\n\f\r />])", re.IGNORECASE | re.ASCII)


def _tag_end(html: str, start: int) -> int | None:
    quote = None

    for index in range(start, len(html)):
        character = html[index]
        if quote is not None:
            if character == quote:
                quote = None
        elif character in "\"'":
            quote = character
        elif character == ">":
            return index + 1

    return None


def _strip_scripts_once(html: str) -> tuple[str, bool]:
    parts = []
    unchanged_start = 0
    search_start = 0
    changed = False

    while match := _SCRIPT_START.search(html, search_start):
        opening_end = _tag_end(html, match.end())
        if opening_end is None:
            search_start = match.end()
            continue

        closing_match = _SCRIPT_END.search(html, opening_end)
        if closing_match is None:
            removal_end = len(html)
        else:
            closing_end = _tag_end(html, closing_match.end())
            removal_end = len(html) if closing_end is None else closing_end

        parts.append(html[unchanged_start : match.start()])
        unchanged_start = removal_end
        search_start = removal_end
        changed = True

    if not changed:
        return html, False

    parts.append(html[unchanged_start:])
    return "".join(parts), True


def sanitize(html: str) -> str:
    """Remove script elements while preserving all other input verbatim."""
    while True:
        html, changed = _strip_scripts_once(html)
        if not changed:
            return html

